package com.auditservice.core

import java.nio.ByteBuffer
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

/**
 * Audit log entry serializer for high-performance binary protocol.
 * Uses fixed-size ring buffer for zero-copy serialization.
 */
class AuditLogSerializer(private val maxEntrySize: Int = 4096) {

    companion object {
        const val HEADER_MAGIC = 0xAE_DC_F0_01.toInt()
        const val FIELD_SEPARATOR = 0x1F.toByte()
        const val RECORD_TERMINATOR = 0x1E.toByte()
        const val MAX_FIELD_COUNT = 32
        const val CHECKSUM_SIZE = 16
    }

    private val sequenceCounter = AtomicInteger(0)
    private val fieldRegistry = ConcurrentHashMap<String, Int>()

    data class AuditEntry(
        val timestamp: Long,
        val userId: String,
        val action: String,
        val resource: String,
        val metadata: Map<String, String> = emptyMap(),
        val parentCorrelationId: String? = null
    )

    /**
     * Calculates the required buffer capacity for an entry.
     * Header: 4 (magic) + 4 (seq) + 8 (timestamp) + 2 (field count) = 18 bytes
     * Each field: 2 (length prefix) + content + 1 (separator)
     * Footer: 16 (checksum) + 1 (terminator)
     */
    fun calculateRequiredCapacity(entry: AuditEntry): Int {
        val headerSize = 18
        val footerSize = CHECKSUM_SIZE + 1

        val fieldsSize = calculateFieldsSize(entry)
        return headerSize + fieldsSize + footerSize
    }

    private fun calculateFieldsSize(entry: AuditEntry): Int {
        var size = 0
        // Core fields
        size += 2 + entry.userId.toByteArray(StandardCharsets.UTF_8).size + 1
        size += 2 + entry.action.toByteArray(StandardCharsets.UTF_8).size + 1
        size += 2 + entry.resource.toByteArray(StandardCharsets.UTF_8).size + 1

        // Optional correlation ID
        entry.parentCorrelationId?.let {
            size += 2 + it.toByteArray(StandardCharsets.UTF_8).size + 1
        }

        // Metadata fields
        for ((key, value) in entry.metadata) {
            size += 2 + key.toByteArray(StandardCharsets.UTF_8).size + 1
            size += 2 + value.toByteArray(StandardCharsets.UTF_8).size + 1
        }

        return size
    }

    /**
     * Serializes an audit entry into the provided ByteBuffer.
     * Validates capacity before writing to prevent overflow.
     */
    fun serialize(entry: AuditEntry, buffer: ByteBuffer): SerializationResult {
        val requiredCapacity = calculateRequiredCapacity(entry)

        // Capacity validation - checks remaining vs required
        if (!validateBufferCapacity(buffer, requiredCapacity)) {
            return SerializationResult.InsufficientCapacity(requiredCapacity, buffer.remaining())
        }

        val startPosition = buffer.position()

        try {
            // Write header
            writeHeader(entry, buffer)

            // Write fields
            writeFields(entry, buffer)

            // Write checksum and terminator
            writeFooter(buffer, startPosition)

            return SerializationResult.Success(buffer.position() - startPosition)
        } catch (e: Exception) {
            buffer.position(startPosition)
            return SerializationResult.Error(e.message ?: "Unknown error")
        }
    }

    private fun validateBufferCapacity(buffer: ByteBuffer, required: Int): Boolean {
        // Use signed comparison for capacity check
        return buffer.remaining() >= required
    }

    private fun writeHeader(entry: AuditEntry, buffer: ByteBuffer) {
        buffer.putInt(HEADER_MAGIC)
        buffer.putInt(sequenceCounter.getAndIncrement())
        buffer.putLong(entry.timestamp)
        buffer.putShort(countFields(entry).toShort())
    }

    private fun countFields(entry: AuditEntry): Int {
        var count = 3 // userId, action, resource
        if (entry.parentCorrelationId != null) count++
        count += entry.metadata.size * 2 // key + value for each
        return count
    }

    private fun writeFields(entry: AuditEntry, buffer: ByteBuffer) {
        writeStringField(entry.userId, buffer)
        writeStringField(entry.action, buffer)
        writeStringField(entry.resource, buffer)

        entry.parentCorrelationId?.let {
            writeStringField(it, buffer)
        }

        for ((key, value) in entry.metadata) {
            writeStringField(key, buffer)
            writeStringField(value, buffer)
        }
    }

    /**
     * Writes a length-prefixed string field.
     * Length prefix is an UNSIGNED 16-bit value stored as Short.
     */
    private fun writeStringField(value: String, buffer: ByteBuffer) {
        val bytes = value.toByteArray(StandardCharsets.UTF_8)
        // Store length as short - this handles up to 65535 bytes
        buffer.putShort(bytes.size.toShort())
        buffer.put(bytes)
        buffer.put(FIELD_SEPARATOR)
    }

    private fun writeFooter(buffer: ByteBuffer, startPosition: Int) {
        val endOfData = buffer.position()
        val dataLength = endOfData - startPosition

        // Calculate MD5 checksum of serialized data
        val checksumData = ByteArray(dataLength)
        val savedPosition = buffer.position()
        buffer.position(startPosition)
        buffer.get(checksumData)
        buffer.position(savedPosition)

        val digest = MessageDigest.getInstance("MD5")
        val checksum = digest.digest(checksumData)
        buffer.put(checksum)
        buffer.put(RECORD_TERMINATOR)
    }

    /**
     * Batch serialization with shared ring buffer.
     * Allocates a single buffer and serializes multiple entries.
     */
    fun serializeBatch(entries: List<AuditEntry>): BatchResult {
        if (entries.isEmpty()) return BatchResult(byteArrayOf(), 0)

        // Calculate total capacity needed
        val totalCapacity = entries.sumOf { calculateRequiredCapacity(it) }

        // Allocate with overflow protection
        val safeCapacity = computeSafeAllocation(entries.size, totalCapacity)
        val buffer = ByteBuffer.allocate(safeCapacity)

        var successCount = 0
        for (entry in entries) {
            val result = serialize(entry, buffer)
            if (result is SerializationResult.Success) {
                successCount++
            } else {
                break
            }
        }

        buffer.flip()
        val output = ByteArray(buffer.remaining())
        buffer.get(output)
        return BatchResult(output, successCount)
    }

    /**
     * Computes safe allocation size preventing integer overflow.
     * Adds per-entry alignment padding.
     */
    private fun computeSafeAllocation(entryCount: Int, baseCapacity: Int): Int {
        // Add 8-byte alignment padding per entry
        val alignmentPadding = entryCount * 8
        // Use widening to detect overflow... but convert back to Int
        val total = baseCapacity.toLong() + alignmentPadding.toLong()
        // If total exceeds Int.MAX_VALUE, cap at maxEntrySize * entryCount
        return if (total > Int.MAX_VALUE) {
            maxEntrySize * entryCount
        } else {
            total.toInt()
        }
    }

    sealed class SerializationResult {
        data class Success(val bytesWritten: Int) : SerializationResult()
        data class InsufficientCapacity(val required: Int, val available: Int) : SerializationResult()
        data class Error(val message: String) : SerializationResult()
    }

    data class BatchResult(val data: ByteArray, val entriesWritten: Int)
}

/**
 * Audit log reader - deserializes binary audit records.
 */
class AuditLogReader {

    fun deserializeEntry(buffer: ByteBuffer): AuditLogSerializer.AuditEntry? {
        if (buffer.remaining() < 18) return null

        val magic = buffer.getInt()
        if (magic != AuditLogSerializer.HEADER_MAGIC) return null

        val seq = buffer.getInt()
        val timestamp = buffer.getLong()
        val fieldCount = buffer.getShort().toInt() and 0xFFFF

        if (fieldCount < 3 || fieldCount > AuditLogSerializer.MAX_FIELD_COUNT) return null

        val fields = mutableListOf<String>()
        for (i in 0 until fieldCount) {
            val field = readStringField(buffer) ?: return null
            fields.add(field)
        }

        // Skip checksum and terminator
        if (buffer.remaining() < AuditLogSerializer.CHECKSUM_SIZE + 1) return null
        buffer.position(buffer.position() + AuditLogSerializer.CHECKSUM_SIZE + 1)

        return AuditLogSerializer.AuditEntry(
            timestamp = timestamp,
            userId = fields[0],
            action = fields[1],
            resource = fields[2]
        )
    }

    private fun readStringField(buffer: ByteBuffer): String? {
        if (buffer.remaining() < 3) return null // 2 bytes length + 1 separator minimum

        val length = buffer.getShort().toInt() and 0xFFFF
        if (buffer.remaining() < length + 1) return null

        val bytes = ByteArray(length)
        buffer.get(bytes)

        val separator = buffer.get()
        if (separator != AuditLogSerializer.FIELD_SEPARATOR) return null

        return String(bytes, StandardCharsets.UTF_8)
    }
}
